mapper.select:
insert into document_file (
    file_master_seq
    ,file_seq
    ,file_name
    ,file_path
    ,file_type
    ,file_size
    ,file_ext
    ,reg_dttm
    ,reg_id
    /* Add document_seq if it's part of FileInfoDto and your table */
    /* ,document_seq */
) values (
    #{fileMasterSeq}
    ,nextval('file_seq')
    ,#{fileName}
    ,#{filePath}
    ,#{fileType}
    ,#{fileSize}
    ,#{fileExt}
    ,now()
    ,coalesce(#{regId},'system')
    /* ,#{documentSeq} */
)
returning currval('file_seq')

select file_master_seq, file_seq, file_name, file_path, file_type, file_size, file_ext, reg_dttm /* Add document_seq if relevant for this list and available in the table */ from document_file where 1=1
and file_master_seq = #{fileMasterSeq}
order by reg_dttm desc
